import java.util.*;
import java.io.*;

public class Div680 {
    static int size, modulus, bias;
    static int[][][] memo;

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String[] tokens = br.readLine().split(" ");
        size = Integer.parseInt(tokens[0]);
        modulus = Integer.parseInt(tokens[1]);
        bias = size * (size - 1);
        memo = new int[2][size][2 * bias + 1];
        for (int i = 0; i < 2; i++) {
            for (int j = 0; j < size; j++) {
                Arrays.fill(memo[i][j], -1);
            }
        }
        System.out.println(solve(0));
        br.close();
    }

    static long solve(int pos) {
        if (pos == size - 1) return 0L;
        long acc = ((long)(size - pos) * solve(pos + 1)) % modulus;
        for (int p = 0; p < size - pos; p++) {
            for (int q = p + 1; q < size - pos; q++) {
                acc = (acc + evaluate(1, pos + 1, p - q)) % modulus;
            }
        }
        return acc;
    }

    static int evaluate(int flag, int index, int diff) {
        if (index == size) return diff > 0 ? 1 : 0;
        int key = diff + bias;
        if (memo[flag][index][key] != -1) return memo[flag][index][key];
        int remaining = size - index;
        long sum = 0;
        for (int left = 0; left < remaining; left++) {
            int rightStart = (flag == 1) ? 0 : left;
            for (int right = rightStart; right < remaining; right++) {
                int nextFlag = flag | ((left < right) ? 1 : 0);
                sum = (sum + evaluate(nextFlag, index + 1, diff + left - right)) % modulus;
            }
        }
        return memo[flag][index][key] = (int)sum;
    }

    static long gcd(long x, long y) {
        while (x != 0) {
            long temp = x;
            x = y % x;
            y = temp;
        }
        return y;
    }

    static class Reader {
        private BufferedReader input;
        private StringTokenizer tokenizer;

        public Reader(InputStream stream) {
            input = new BufferedReader(new InputStreamReader(stream));
        }

        public Reader(FileReader fr) {
            input = new BufferedReader(fr);
        }

        public String token() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                tokenizer = new StringTokenizer(input.readLine());
            }
            return tokenizer.nextToken();
        }

        public int integer() throws IOException { return Integer.parseInt(token()); }
        public long integer64() throws IOException { return Long.parseLong(token()); }
        public String line() throws IOException { return input.readLine(); }

        public double decimal() throws IOException {
            String s = token();
            boolean negative = s.charAt(0) == '-';
            if (negative) s = s.substring(1);
            double result = 0;
            double fraction = 1;
            boolean afterPoint = false;
            for (char c : s.toCharArray()) {
                if (c == '.') {
                    afterPoint = true;
                    continue;
                }
                result = result * 10 + (c - '0');
                if (afterPoint) fraction *= 10;
            }
            return (result / fraction) * (negative ? -1 : 1);
        }

        public boolean ready() throws IOException { return input.ready(); }
    }
}
